package com.blog.entity; import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="comments") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class Comment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Lob @Column(nullable=false) private String content; @Column(nullable=false,updatable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id") private User user; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="post_id") private Post post; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="parent_comment_id") private Comment parentComment; @OneToMany(mappedBy="parentComment",cascade=CascadeType.REMOVE) private List<Comment> replies=new ArrayList<>(); @PrePersist void created(){createdAt=updatedAt=Instant.now();} @PreUpdate void updated(){updatedAt=Instant.now();} }
